<template><Card class="s1-ui"><header class="ui-header"><div><h2>{{storeName}} · {{editingMaterials?'编辑进件材料':'二级商户关系'}}</h2><p v-if="selected"><Tag :color="relation.mode==='MOCK'?'orange':'blue'">{{status(relation.mode)}}</Tag><StatusTag :value="relation.applicationState"/> · {{relation.enabled?'本地启用':'本地停用'}}</p><p v-if="selected" class="ui-meta">关系 {{relation.id}} · v{{relation.version}} · 配置 {{configName}} · v{{relation.configVersion}}</p></div><div class="ui-actions"><Button v-if="editingMaterials" @click="cancelMaterials">返回关系详情</Button><Button v-else @click="back">返回关系列表</Button><Button :disabled="dirty||uploading" @click="reload">重新读取</Button></div></header><PageStatus v-bind="$data" :target="pendingTarget" @recover="recover()" @retry="recover(true)" @abandon="abandon"/><div v-if="selected"><ChannelMaterials v-if="editingMaterials" :key="relation.id+':'+relation.version" :value="selected.materials.fields" :scope="relation.id" :protected-fields="selected.materials.protectedFields" :licenses="licenses" :disabled="blocked" :error="error" @dirty="dirty=true" @save="saveMaterials" @cancel="cancelMaterials"/><div v-else><Alert v-if="relation.mode==='REAL'" type="warning" show-icon>本候选环境未授权真实渠道出站；提交和渠道回查不会作为本批自动执行。当前真实资格保持待核验。</Alert><Tabs v-model="tab" :animated="false" @on-click="clearAction"><TabPane label="关系摘要与核验" name="overview"><DetailSection title="当前关系"><FieldRow label="商户" :value="storeName"/><FieldRow label="渠道配置" :value="configName"/><FieldRow label="二级商户号（掩码）" :value="relation.subMchidMasked"/><FieldRow label="关系状态" :value="relation.replaced?'历史替换关系':relation.enabled?'本地启用':'本地停用'"/><FieldRow label="申请状态" :value="status(relation.applicationState)"/><FieldRow label="渠道原始状态码" :value="status(relation.rawState)"/><FieldRow label="业务申请号" :value="relation.outRequestNo"/><FieldRow label="渠道申请号" :value="relation.applymentId"/><FieldRow label="能力状态" :value="status(relation.capabilityState)"/><FieldRow label="最近同步结果" :value="status(relation.lastSyncState)"/><FieldRow label="最近核验时间" :value="date(relation.verifiedAt)"/><FieldRow label="真实资格" :value="status(relation.realQualification)"/><FieldRow label="平台接收关系" :value="receiverName"/></DetailSection><DetailSection title="能力核验事实"><FieldRow label="支付能力" :value="evidence.paymentEnabled"/><FieldRow label="支付应用关联" :value="evidence.appIdLinked"/><FieldRow label="佣金关系能力" :value="evidence.profitsharingEnabled"/><FieldRow label="渠道比例上限" :value="percent(evidence.maxRateBps)"/><FieldRow label="证据来源" :value="evidence.source==='S1_TEST_PERSISTENT_SIMULATION'?'持久模拟渠道':evidence.source||'未提供'"/><FieldRow label="证据模式" :value="status(evidence.sourceMode)"/></DetailSection></TabPane><TabPane label="当前材料" name="materials"><DetailSection title="主体与经营授权"><FieldRow label="商户简称" :value="materials.shortName"/><FieldRow label="行业" :value="materials.industryName"/><FieldRow label="结算规则编号" :value="materials.settlementId"/><FieldRow label="使用授权依据" :value="materials.authorizationBasis" wide/></DetailSection><AttachmentList :value="materials.licenseFileId" title="营业执照" purpose="QUALIFICATION"/><DocumentSummary title="法定代表人证件" :value="materials.legalId" prefix="legalId" :protected-fields="protectedFields"/><DetailSection title="渠道管理员"><FieldRow label="联系人身份" :value="status(contact.type)"/><FieldRow label="姓名" :value="contact.name"/><FieldRow label="电话（受保护）" :value="protectedFields['contact.phone']||'未提供'"/></DetailSection><DocumentSummary v-if="contact.type==='AGENT'" title="代理人证件" :value="contact.identity" prefix="contact.identity" :protected-fields="protectedFields"/><AttachmentList :value="contact.authorizationFileId" title="代理授权" purpose="CHANNEL"/><DetailSection title="结算账户材料"><FieldRow label="账户类型" :value="status(account.type)"/><FieldRow label="开户名称" :value="account.name"/><FieldRow label="账号（受保护）" :value="protectedFields['account.number']||'未提供'"/><FieldRow label="银行渠道编码" :value="account.bankCode"/><FieldRow label="支行联行号" :value="account.bankBranchId"/><FieldRow label="支行名称" :value="account.bankName"/></DetailSection><DetailSection title="经营场景"><FieldRow label="名称" :value="sales.name"/><FieldRow label="商户小程序AppID" :value="sales.merchantMiniAppId"/><FieldRow label="场景链接" :value="sales.url" wide/></DetailSection><AttachmentList :value="sales.qrFileId" title="场景二维码" purpose="CHANNEL"/><DetailSection title="受益所有人" :grid="false"><p>{{materials.soleBeneficialOwner?'法定代表人是唯一受益所有人':'按已保存材料核查，不改变平台Owner身份。'}}</p><DocumentSummary v-for="(owner,index) in materials.beneficialOwners||[]" :key="index" :title="'受益所有人 '+(index+1)" :value="owner" :prefix="'beneficialOwners.'+index" :protected-fields="protectedFields"/></DetailSection><AttachmentList :value="materials.specialQualificationFileIds||[]" title="专项资质" purpose="CHANNEL"/><AttachmentList :value="materials.additionFileIds||[]" title="补充材料" purpose="CHANNEL"/><p class="ui-note">补充说明：{{materials.additionDescription||'未提供'}}</p><p class="ui-meta">材料规范 {{materials.schemaVersion||'未提供'}} · 当前材料 v{{relation.materialVersion}}</p></TabPane><TabPane label="进件待办" name="todo"><DetailSection title="渠道要求" :grid="false"><p>{{status(required.action)}}</p><p class="ui-note">{{required.description||'暂无待办说明'}}</p><Table :columns="todoColumns" :data="required.details||[]" no-data-text="无补正字段说明"/><Button v-if="['LEGAL_VERIFICATION','ADMIN_SIGNING'].includes(required.action)" :disabled="blocked" @click="showAction">查看受控渠道待办</Button><Alert v-if="channelAction" show-icon><p>{{channelAction.instruction}}</p><p>展示截止：{{date(channelAction.displayUntil)}}</p><a v-if="channelAction.url" :href="channelAction.url" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">由指定当事人打开微信入口</a><Button size="small" @click="clearAction">隐藏待办</Button></Alert></DetailSection></TabPane><TabPane label="材料与操作历史" name="history"><h3>材料版本</h3><Table :data="selected.materialRevisions" :columns="materialColumns"><template slot="summary" slot-scope="{row}">授权依据：{{row.summary.authorizationRecorded?'已记录':'未记录'}}；文件数 {{row.summary.fileCount}}<p class="ui-meta">账户 {{row.summary.accountMasked||'未提供'}} · 联系电话 {{row.summary.contactMasked||'未提供'}}</p></template><template slot="time" slot-scope="{row}">{{date(row.at)}}</template></Table><h3 style="margin-top:24px">渠道操作</h3><Table :data="selected.operations" :columns="operationColumns"><template slot="action" slot-scope="{row}">{{action(row.action)}}</template><template slot="state" slot-scope="{row}"><StatusTag :value="row.status"/><p class="ui-meta">第 {{row.attempt}} 次；序列 {{row.sequence}}</p></template><template slot="result" slot-scope="{row}">{{row.failureCode?reason(row.failureCode):row.result?status(row.result.state||row.result.code):'未提供'}}<p v-if="row.result" class="ui-meta">{{row.result.subMchidMasked||row.result.applymentId||''}}</p></template><template slot="time" slot-scope="{row}">{{date(row.completedAt||row.createdAt)}}</template></Table></TabPane></Tabs><footer class="ui-footer-actions"><Button @click="back">返回列表</Button><Button v-if="editableMaterials" :disabled="blocked" @click="openMaterials">编辑材料</Button><Button v-if="editableMaterials" type="primary" :disabled="blocked||relation.mode!=='MOCK'" @click="execute('submit')">提交当前材料版本</Button><Button v-else :disabled="blocked||relation.mode!=='MOCK'" @click="execute('query')">按原申请号回查</Button><Button :disabled="blocked" @click="execute(relation.enabled?'disable':'enable')">{{relation.enabled?'停用关联':'启用关联'}}</Button><Button :disabled="blocked" @click="replacementShow=true">建立替换关系</Button><Button v-if="can('channel.receiver')" :disabled="blocked" @click="receiverForm={receiverId:relation.receiverId||'',reason:''};receiverShow=true">关联平台接收方</Button></footer></div></div><RelationForm :visible="replacementShow" :previous="selected?relation:null" :disabled="blocked" :busy="busy" :error="error" @dirty="dirty=true" @save="replace" @cancel="replacementShow=false;dirty=false"/><Modal v-model="receiverShow" title="关联平台接收方" width="800" :mask-closable="false" footer-hide><div class="s1-ui"><p class="ui-note">仅可选择同配置、同模式的关系。停用或未核验不会因此变为有效；留空明确解除关联。</p><Form :model="receiverForm" :label-width="140"><FormItem label="平台接收关系"><BusinessSelect v-model="receiverForm.receiverId" type="receivers" :params="{configId:relation.configId}" :disabled="blocked"/></FormItem><FormItem label="关联原因" required><Input v-model="receiverForm.reason" type="textarea" maxlength="500" :disabled="blocked"/></FormItem></Form><p v-if="error" class="ui-error">{{error}}</p><footer class="ui-form-footer"><Button @click="receiverShow=false">取消</Button><Button type="primary" :loading="busy" :disabled="blocked" @click="saveReceiver">保存关联</Button></footer></div></Modal></Card></template>
<script>import page from './page';import PageStatus from './components/PageStatus';import StatusTag from './components/StatusTag';import DetailSection from './components/DetailSection';import FieldRow from './components/FieldRow';import BusinessSelect from './components/BusinessSelect';import AttachmentList from './components/AttachmentList';import DocumentSummary from './components/DocumentSummary';import RelationForm from './components/RelationForm';import ChannelMaterials from './ChannelMaterials';import {stage1Confirm} from '../confirm';export default {mixins:[page],components:{PageStatus,StatusTag,DetailSection,FieldRow,BusinessSelect,AttachmentList,DocumentSummary,RelationForm,ChannelMaterials},data:()=>({storeName:'名称读取中',configName:'名称读取中',receiverName:'未关联',licenses:[],receiverShow:false,receiverForm:{},replacementShow:false,channelAction:null,actionTimer:null,actionTicket:0,todoColumns:[{title:'待补字段',key:'field',minWidth:180},{title:'渠道说明',key:'reason',minWidth:300}],materialColumns:[{title:'材料版本',key:'revision',width:100},{title:'安全摘要',slot:'summary',minWidth:330},{title:'时间',slot:'time',minWidth:185}],operationColumns:[{title:'操作',slot:'action',minWidth:120},{title:'状态',slot:'state',minWidth:170},{title:'结果／原因',slot:'result',minWidth:230},{title:'配置版本',key:'configVersion',width:100},{title:'时间',slot:'time',minWidth:185}]}),computed:{relation(){return this.selected&&this.selected.relation||{};},materials(){return this.selected&&this.selected.materials.fields||{};},protectedFields(){return this.selected&&this.selected.materials.protectedFields||{};},contact(){return this.materials.contact||{};},account(){return this.materials.account||{};},sales(){return this.materials.sales||{};},evidence(){return this.relation.capabilityEvidence||{};},required(){return this.relation.requiredActions||{};},editableMaterials(){return ['DRAFT','NEED_CORRECTION'].includes(this.relation.applicationState);},editingMaterials(){return this.$route.query.edit==='materials'&&this.editableMaterials;}},watch:{'$route.params.id'(){this.clearAction();this.dirty=false;this.reload();}},mounted(){this.reload();},beforeDestroy(){this.clearAction();},methods:{reload(){this.clearAction();return this.latest(async()=>{const value=await this.read('/submerchants/'+this.$route.params.id),row=value.relation;const [stores,configs]=await Promise.all([this.ui('/lookups/stores',{selected:row.storeId,pageSize:1}),this.ui('/lookups/channel-configs',{selected:row.configId,pageSize:1})]);let receiver='未关联';if(row.receiverId&&this.can('channel.receiver')){const v=await this.ui('/lookups/receivers',{selected:row.receiverId,configId:row.configId,pageSize:1});receiver=v.records[0]&&v.records[0].name||'原引用不可读';}return {value,store:stores.records[0]&&stores.records[0].name,config:configs.records[0]&&configs.records[0].name,receiver};},v=>{this.selected=v.value;this.storeName=v.store||'商户名称未提供';this.configName=v.config||'配置名称未提供';this.receiverName=v.receiver;if(this.editingMaterials)this.loadLicenses();},()=>{this.selected=null;});},async loadLicenses(){const id=this.relation.id,store=this.relation.storeId;try{const profile=await this.ui('/stores/'+store);if(this.selected&&this.relation.id===id)this.licenses=profile.qualifications.versions.filter(q=>q.type==='BUSINESS_LICENSE'&&['ACTIVE','APPROVED'].includes(q.status)).flatMap(q=>(q.details.fileIds||[]).map(id=>({id,label:'营业执照 v'+q.revision+' · '+id})));}catch(e){this.error=e.message;}},openMaterials(){this.clearAction();this.loadLicenses();this.$router.push({path:this.$route.path,query:{...this.$route.query,edit:'materials'}});},cancelMaterials(){if(this.uploading)return;const close=()=>{this.dirty=false;const q={...this.$route.query};delete q.edit;this.$router.replace({path:this.$route.path,query:q});};if(this.dirty)stage1Confirm({title:'放弃未保存材料？',content:'不会提交当前材料修改；未决上传仍需回查。',onOk:close});else close();},async saveMaterials(body){const row=this.relation;try{const value=await this.run('/submerchants/'+row.id+'/materials',{expectedVersion:row.version,...body},'PUT');if(value){this.dirty=false;const query={...this.$route.query};delete query.edit;await this.$router.replace({path:this.$route.path,query});await this.reload();}}catch(_){}},async execute(action){this.clearAction();const row=this.relation;const value=await this.command('/submerchants/'+row.id+'/'+action,{submit:'提交当前材料版本',query:'按原业务申请号回查',enable:'启用已核验关联',disable:'停用关联并失效相应资格'}[action],{expectedVersion:row.version},this.storeName+' · '+this.status(row.mode)+' · v'+row.version+'。未知结果继续查询原申请，不新建申请。');if(value)await this.reload();},async replace(body){try{const result=await this.run('/submerchants',body);if(result){this.replacementShow=false;this.dirty=false;this.detail(result.id);}}catch(_){}},async saveReceiver(){if(!String(this.receiverForm.reason||'').trim()){this.error='请填写关联原因。';return;}try{const row=this.relation,result=await this.run('/submerchants/'+row.id+'/receiver',{expectedVersion:row.version,receiverId:this.receiverForm.receiverId||null,reason:this.receiverForm.reason},'PUT');if(result){this.receiverShow=false;await this.reload();}}catch(_){}},clearAction(){this.actionTicket++;clearTimeout(this.actionTimer);this.channelAction=null;},async showAction(){this.clearAction();const row=this.relation,ticket=this.actionTicket;try{const value=await this.read('/submerchants/'+row.id+'/required-action',{expectedVersion:row.version});if(ticket!==this.actionTicket||!this.selected||this.relation.id!==row.id||this.relation.version!==row.version)return;const remaining=Date.parse(value.displayUntil)-Date.now();if(remaining<=0)throw Error('渠道待办已过期，请回查原申请。');if(value.url){const url=new URL(value.url);if(url.protocol!=='https:'||url.hostname!=='pay.weixin.qq.com'||url.pathname!=='/public/apply4ec_sign/s'||url.username||url.password||url.port||url.hash)throw Error('渠道待办目标未验证。');}this.channelAction=value;this.actionTimer=setTimeout(()=>this.clearAction(),Math.min(remaining,300000));}catch(e){if(ticket===this.actionTicket)this.error=e.message;}}}};</script>
